var L={
 'zh-CN':{ph:'加一条要做的事…',add:'添加',empty:'没有待办',done:'完成',handle:'处理',del:'删除',sure:'确定删除?',ask:'处理这条待办: '},
 'zh-TW':{ph:'加一條要做的事…',add:'新增',empty:'沒有待辦',done:'完成',handle:'處理',del:'刪除',sure:'確定刪除?',ask:'處理這條待辦: '},
 'ja':{ph:'やることを追加…',add:'追加',empty:'やることはありません',done:'完了',handle:'対応',del:'削除',sure:'削除しますか?',ask:'このやることに対応して: '},
 'en':{ph:'Add something to do…',add:'Add',empty:'Nothing to do',done:'Done',handle:'Handle',del:'Delete',sure:'Delete?',ask:'Handle this to-do: '}
};
var S=L['zh-CN'],box=document.getElementById('list'),inp=document.getElementById('t'),btn=document.getElementById('add'),arm=null;
function tx(s){return document.createTextNode(s==null?'':String(s));}
function el(tag,cls,text){var e=document.createElement(tag);if(cls)e.className=cls;if(text!=null)e.appendChild(tx(text));return e;}
function draw(rows){
 box.innerHTML='';
 if(!rows||!rows.length){box.appendChild(el('div','empty',S.empty));butlerUI.resize(document.body.scrollHeight);return;}
 rows.forEach(function(r){
  var row=el('div','row'),t=el('span','tt',r.title);t.title=r.title+(r.note?'\n'+r.note:'')+(r.who?'\n· '+r.who:'');
  row.appendChild(t);
  if(r.who)row.appendChild(el('span','who',r.who));
  var b1=el('button','ok',S.done);b1.onclick=function(){butlerUI.call('todo.done',{id:r.id}).then(load);};
  var b2=el('button','go',S.handle);b2.onclick=function(){butlerUI.call('todo.handle',{text:S.ask+'#'+r.id+' '+r.title+(r.note?' — '+r.note:'')});};
  var b3=el('button','x',S.del);b3.onclick=function(){
   if(arm!==r.id){arm=r.id;b3.textContent=S.sure;b3.className='x armed';return;}
   arm=null;butlerUI.call('todo.remove',{id:r.id}).then(load);};
  row.appendChild(b1);row.appendChild(b2);row.appendChild(b3);box.appendChild(row);
 });
 butlerUI.resize(document.body.scrollHeight);
}
function load(){butlerUI.call('todo.list',{}).then(function(r){if(r&&r.ok)draw(r.rows||[]);});}
function add(){var v=inp.value.trim();if(!v)return;inp.value='';butlerUI.call('todo.add',{title:v}).then(load);}
btn.onclick=add;inp.onkeydown=function(e){if(e.key==='Enter'&&!e.isComposing)add();};
butlerUI.onInit(function(d){S=L[d.locale]||L[String(d.locale||'').slice(0,2)]||L.en;inp.placeholder=S.ph;btn.textContent=S.add;load();setInterval(load,4000);});
